import { RailwayClient } from '@railway/sdk';

interface ServiceInfo {
  id: string;
  name: string;
}

async function listProjectServices(
  projectId: string
): Promise<ServiceInfo[]> {
  const client = new RailwayClient({
    token: process.env.RAILWAY_TOKEN!,
  });

  const services = await client.services.list({ projectId });

  return services.map((service) => ({
    id: service.id,
    name: service.name,
  }));
}

async function triggerRedeployment(
  serviceId: string,
  environmentId: string
): Promise<void> {
  const client = new RailwayClient({
    token: process.env.RAILWAY_TOKEN!,
  });

  await client.deployments.create({
    serviceId,
    environmentId,
  });

  console.log(`Redeployment triggered for service ${serviceId}`);
}

// List services and redeploy the first one
const services = await listProjectServices(process.env.RAILWAY_PROJECT_ID!);
console.log('Services:', services);

if (services.length > 0) {
  await triggerRedeployment(services[0].id, process.env.RAILWAY_ENVIRONMENT_ID!);
}
